//! Bake the commit this build came from into the binary, and run tauri-build.
//!
//! The probe has had the build stamp since its first sweep. The product had
//! not, and on 2026-08-06 a reader pasted a session log that neither of us
//! could date: a defect fixed an hour earlier was read as still present
//! because there was no way to tell which binary had produced the lines.
//!
//! `tauri_build` generates the WebView2 bootstrapper and bundles the frontend
//! assets declared in `tauri.conf.json`.
//!
//! Application command permissions are autogenerated from the COMMANDS list.
//! This enables per-window capability restrictions in capabilities/*.json.

use tauri_build::{AppManifest, Attributes};

/// All registered Tauri commands.
///
/// This list must be kept in sync with the invoke_handler in src/tauri_app.rs.
/// The build script uses it to autogenerate allow-*/deny-* permissions that
/// capabilities can reference for per-window access control.
const COMMANDS: &[&str] = &[
    // System/diagnostics
    "check_provider",
    "export_diagnostics",
    "get_diagnostic_events",
    "get_diagnostics",
    "get_local_ai_status",
    "get_runtime_status",
    "run_health_check",
    // Settings
    "get_settings",
    "save_settings",
    "set_autostart",
    // Models/AI
    "list_models",
    "test_model",
    // Library
    "library_delete",
    "library_distinct_apps",
    "library_distinct_source_languages",
    "library_distinct_tags",
    "library_distinct_target_languages",
    "library_export",
    "library_export_json",
    "library_export_jsonl",
    "library_get",
    "library_get_tags",
    "library_import_jsonl",
    "library_later_count",
    "library_query",
    "library_review_session",
    "library_secure_wipe",
    "library_set_review_state",
    "library_set_tags",
    "library_update_note",
    // History
    "history_count",
    "history_delete",
    "history_list",
    "history_promote",
    "history_prune",
    // Recent
    "recent_list",
    // Mori transfer
    "mori_send_item",
    "mori_status",
    // Lifecycle
    "request_pause_toggle",
    "request_quit",
    // Detail view
    "detail_copy",
    "detail_open_in_library",
    "detail_read",
    "detail_request_explain",
    "detail_save",
    "detail_save_note",
];

fn main() {
    lens_build_stamp::emit();

    tauri_build::try_build(Attributes::new().app_manifest(AppManifest::new().commands(COMMANDS)))
        .expect("failed to run tauri-build with app command manifest");
}
